/// <summary>
/// Constructs the reference identities used to populate the <c>METOrderExtractScreen</c> form.
/// </summary>
public class METOrderExtractScreenProcessor
{
    METOrderExtractScreenTmp                metOrderExtractScreenTmp;
    MEtOrderExtractScreenParameters         metOrderExtractScreenParameters;
    SalesTable                              salesTable;
    SalesLine                               salesLine;
    SalesLine                               salesLineIns;
    MetItemSiteSettingsSetup                itemSiteSettings;
    METWHSPhysDimUOMSite                    metWHSPhysDimUOMSite;
    METWHSPhysDimUOMSite                    metWHSPhysDimUOMSiteJoin;
    InventDim                               inventDim;
    METOrderExtractScreenUOMView            metOrderExtractScreenUOMView;
    METOrderExtractScreenPhysDimView        metOrderExtractScreenPhysDimView;
    WHSPhysDimUOM                           whsPhysDimUOM;
    WHSPhysDimUOM                           whsPhysDimUOMJoin;
    METOrderExtractScreenUOMViewTmp         metOrderExtractScreenUOMViewTmp;
    ReqItemTable                            reqItemTable;
    METReqItemTable                         metReqItemTable;        
    InventDim                               inventDimReq;
    METInventLocation                       metInventLocation;

    Factor                                  factor;
    InventQty                               cases;
    InventSiteId                            site;
    InventLocationId                        warehouse;
    METRoute                                route;
    SalesShippingDateConfirmed              shippingDateFrom;
    SalesShippingDateConfirmed              shippingDateTo;
    METFilterCodeone                        category;
    Volume                                  totalVolume;
    METOrderExtractStatus                   extracted;
    METTotalPallets                         totalPallets;

    Map                                     volumeMap;
    MapEnumerator                           mapEnum;

}

Method.Source:
/// <summary>
/// Sets total pallets
/// </summary>
/// <param name = "_pallets">Total palletslume</param>
/// <returns>Pallets</returns>
public METTotalPallets parmTotalpallets(METTotalPallets _pallets = totalPallets)
{
    totalPallets = _pallets;
    return totalPallets;
}

/// <summary>
/// set or get <c>MEtOrderExtractScreenParameters</c> class instance.
/// </summary>
/// <param name = "_metOrderExtractScreenParameters"><c>MEtOrderExtractScreenParameters</c> class instance.</param>
/// <returns><c>MEtOrderExtractScreenParameters</c> class instance</returns>
public MEtOrderExtractScreenParameters parmMETOrderExtractScreenParams(
    MEtOrderExtractScreenParameters _metOrderExtractScreenParameters)
{
    MEtOrderExtractScreenParameters = _metOrderExtractScreenParameters;
    return MEtOrderExtractScreenParameters;
}

    /// <summary>
    /// set or get <c>METOrderExtractScreenTmp</c> table instance.
    /// </summary>
    /// <param name = "_metOrderExtractScreenTmp"><c>METOrderExtractScreenTmp</c> table instance</param>
    /// <returns><c>METOrderExtractScreenTmp</c> table instance</returns>
    public METOrderExtractScreenTmp parmMETOrderExtractScreenTmp(
        METOrderExtractScreenTmp _metOrderExtractScreenTmp = metOrderExtractScreenTmp)
    {
        metOrderExtractScreenTmp.linkPhysicalTableInstance(_metOrderExtractScreenTmp);

        return metOrderExtractScreenTmp;
    }

/// <summary> /// Extracts all the orders by salesid and category based on the filters. /// </summary> public void insertOrders() { //Case1: Insert records group by SalesId & Category insert_recordset metOrderExtractScreenTmp(SalesId, LineNum, FilterCodeOne) select SalesId, minof(LineNum) from salesLine group by salesLine.SalesId, itemSiteSettings.FilterCode1 where salesLine.SalesStatus == SalesStatus::Backorder && salesLine.SalesQty > 0 join salesTable where salesTable.SalesId == salesLine.SalesId && (salesTable.DocumentStatus != DocumentStatus::None && salesTable.DocumentStatus != DocumentStatus::Cancelled) && salesTable.SalesType == SalesType::Sales && salesTable.METOrderExtractStatus == extracted && (!route || salesTable.METRoute == route) && (salesTable.ShippingDateConfirmed >= shippingDateFrom && salesTable.ShippingDateConfirmed <= shippingDateTo) join inventDim where inventDim.inventDimId == salesLine.InventDimId && (!site || inventDim.InventSiteId == site) && (!warehouse || inventDim.InventLocationId == warehouse) join FilterCode1 from itemSiteSettings where itemSiteSettings.ItemId == salesLine.ItemId && itemSiteSettings.InventSiteId == inventDim.InventSiteId && (!category || itemSiteSettings.FilterCode1 == category);
//Update order split category code update_recordset metOrderExtractScreenTmp setting OSCCode = metReqItemTable.OSCCode join RecId from salesLine where salesLine.SalesId == metOrderExtractScreenTmp.SalesId && salesLine.LineNum == metOrderExtractScreenTmp.LineNum && salesLine.SalesStatus == SalesStatus::Backorder && salesLine.SalesQty > 0 join RecId from inventDim where inventDim.inventDimId == salesLine.InventDimId && (!site || inventDim.InventSiteId == site) && (!warehouse || inventDim.InventLocationId == warehouse) join ItemType from itemSiteSettings where itemSiteSettings.ItemId == salesLine.ItemId && itemSiteSettings.InventSiteId == inventDim.InventSiteId && itemSiteSettings.FilterCode1 == metOrderExtractScreenTmp.FilterCodeOne join Recid from reqItemTable where reqItemTable.ItemId == salesLine.ItemId join OSCCode from metReqItemTable where metReqItemTable.RefRecId == reqItemTable.RecId exists join inventDimReq where inventDimReq.InventSiteId == inventDim.InventSiteId && InventDimReq.InventLocationId == inventDim.InventLocationId && inventDimReq.inventDimId == reqItemTable.CovInventDimId;
}

    /// <summary>
    /// Calculates the sum of Weight, Volume, Case and Broken case values of the orders extracted.
    /// </summary>
    /// <param name = "_metOrderExtractScreenTmp"><c>METOrderExtractScreenTmp</c> table instance</param>
    public void calculate(METOrderExtractScreenTmp  _metOrderExtractScreenTmp)
    {
        this.parmTotalpallets(0);
        metOrderExtractScreenTmp.linkPhysicalTableInstance(_metOrderExtractScreenTmp);

        //Clear computed values before calculating.
        update_recordset metOrderExtractScreenTmp
            setting weight = 0, Volume = 0, Cases = 0, BrokenCase = 0;

        //METOrderExtractScreenUOMView holds UOM data from custom physical dimensions by site form  by salesId, category, site & warehouse
        //so we insert to temp table for grouping by SalesId & Category
        insert_recordset metOrderExtractScreenUOMViewTmp (SalesId, Category, Weight, Volume)
            select SalesId, Category, sum(Weight), sum(Volume) from metOrderExtractScreenUOMView group by SalesId, category
                where  (!site || metOrderExtractScreenUOMView.InventSiteId == site)
                && (!warehouse || metOrderExtractScreenUOMView.InventLocationId == warehouse);

        //Case2: Update weight, volume for Case1 records where Item, Site & UOM matches
        update_recordset metOrderExtractScreenTmp
            setting weight = metOrderExtractScreenUOMViewTmp.Weight,
                    Volume = metOrderExtractScreenUOMViewTmp.Volume
            join Weight, Volume from metOrderExtractScreenUOMViewTmp
                where metOrderExtractScreenUOMViewTmp.SalesId == metOrderExtractScreenTmp.SalesId
                && metOrderExtractScreenUOMViewTmp.Category == metOrderExtractScreenTmp.FilterCodeOne;

        //Case3: Update weight, volume for Case1 records where Item & Site matches. Conversion required
        while select forupdate metOrderExtractScreenTmp
            join  ItemId, SalesQty, SalesUnit, InventDimId from salesLine
                where  salesLine.SalesStatus == SalesStatus::Backorder
                && salesLine.SalesQty > 0
                && salesLine.SalesId == metOrderExtractScreenTmp.SalesId
            join InventSiteId from inventDim
                where inventDim.inventDimId == salesLine.InventDimId
                && (!site || inventDim.InventSiteId == site)
                && (!warehouse || inventDim.InventLocationId == warehouse)
            join firstonly metWHSPhysDimUOMSite
                where metWHSPhysDimUOMSite.ItemId == salesLine.ItemId
                && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId
                && metWHSPhysDimUOMSite.UOM != salesLine.SalesUnit
            exists join itemSiteSettings 
                where itemSiteSettings.ItemId == salesLine.ItemId
                &&  itemSiteSettings.InventSiteId == inventDim.InventSiteId
                &&  itemSiteSettings.FilterCode1 == metOrderExtractScreenTmp.FilterCodeOne
            notexists join metWHSPhysDimUOMSiteJoin //Tow sales lines with same category and different site UOM
                where metWHSPhysDimUOMSiteJoin.ItemId == salesLine.ItemId
                && metWHSPhysDimUOMSiteJoin.SiteId == inventDim.InventSiteId
                && metWHSPhysDimUOMSiteJoin.UOM == salesLine.SalesUnit
        {
            metOrderExtractScreenTmp.reread();
            ttsbegin;
            factor = EcoResProductUnitConverter::convertForReleasedProduct(
                    metWHSPhysDimUOMSite.ItemId,
                    salesLine.inventDimId,
                    1,
                    EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(metWHSPhysDimUOMSite.UOM),
                    EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(salesLine.SalesUnit),
                    NoYes::No,
                    NoYes::No);

            if (factor)
            {
                metOrderExtractScreenTmp.Weight += salesLine.SalesQty * (metWHSPhysDimUOMSite.Weight/factor);
                metOrderExtractScreenTmp.Volume += salesLine.SalesQty * (metWHSPhysDimUOMSite.displayVolume()/factor);
            }
            metOrderExtractScreenTmp.update();
            ttscommit;
        }

        delete_from metOrderExtractScreenUOMViewTmp;
        //METOrderExtractScreenPhysDimView holds UOM data from standard Physical dimensions form by salesId, category, site & warehouse
        //so we insert to temp table for grouping by SalesId & Category
        insert_recordset metOrderExtractScreenUOMViewTmp (SalesId, Category, Weight, Volume)
            select SalesId, Category, sum(Weight), sum(Volume) from metOrderExtractScreenPhysDimView group by SalesId, category
                where  (!site || metOrderExtractScreenPhysDimView.InventSiteId == site)
                && (!warehouse || metOrderExtractScreenPhysDimView.InventLocationId == warehouse)
            exists join  salesLine
                where  salesLine.SalesStatus == SalesStatus::Backorder
                && salesLine.SalesQty > 0
                && salesLine.ItemId == metOrderExtractScreenPhysDimView.ItemId
                && salesLine.SalesId == metOrderExtractScreenPhysDimView.SalesId
                && salesLine.SalesUnit == metOrderExtractScreenPhysDimView.SalesUnit
            exists join itemSiteSettings
                where itemSiteSettings.ItemId == salesLine.ItemId
                &&  itemSiteSettings.InventSiteId == metOrderExtractScreenPhysDimView.InventSiteId
                &&  itemSiteSettings.FilterCode1 == metOrderExtractScreenPhysDimView.Category
            exists join whsPhysDimUOMJoin
                where whsPhysDimUOMJoin.ItemId == metOrderExtractScreenPhysDimView.ItemId
                && whsPhysDimUOMJoin.UOM == salesLine.SalesUnit
            notexists join metWHSPhysDimUOMSiteJoin
                where metWHSPhysDimUOMSiteJoin.ItemId == salesLine.ItemId
                && metWHSPhysDimUOMSiteJoin.SiteId == metOrderExtractScreenPhysDimView.InventSiteId;

        //Case4: Update weight, volume for Case1 records where Item, Site & UOM matches
        update_recordset metOrderExtractScreenTmp
            setting weight = metOrderExtractScreenTmp.weight + metOrderExtractScreenUOMViewTmp.Weight,
                    Volume = metOrderExtractScreenTmp.Volume + metOrderExtractScreenUOMViewTmp.Volume
            join Weight, Volume from metOrderExtractScreenUOMViewTmp
                where metOrderExtractScreenUOMViewTmp.SalesId == metOrderExtractScreenTmp.SalesId
                && metOrderExtractScreenUOMViewTmp.Category == metOrderExtractScreenTmp.FilterCodeOne;

 
        //Case5: Update weight, volume for records where Item & Site matches. Conversion required
        while select forupdate metOrderExtractScreenTmp
            join  ItemId, SalesQty, SalesUnit, InventDimId from salesLine
                where  salesLine.SalesStatus == SalesStatus::Backorder
                && salesLine.SalesQty > 0
                && salesLine.SalesId == metOrderExtractScreenTmp.SalesId
            join InventSiteId from inventDim
                where inventDim.inventDimId == salesLine.InventDimId
                && (!site || inventDim.InventSiteId == site)
                && (!warehouse || inventDim.InventLocationId == warehouse)
            join whsPhysDimUOM
                where whsPhysDimUOM.ItemId == salesLine.ItemId
                && whsPhysDimUOM.UOM != salesLine.SalesUnit
            exists join itemSiteSettings
                where itemSiteSettings.ItemId == salesLine.ItemId
                &&  itemSiteSettings.InventSiteId == inventDim.InventSiteId
                &&  itemSiteSettings.FilterCode1 == metOrderExtractScreenTmp.FilterCodeOne
            notexists join metWHSPhysDimUOMSite
                where metWHSPhysDimUOMSite.ItemId == salesLine.ItemId
                && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId
        {
            //notexists join is not working and so a seperate call is made
            select firstonly RecId from whsPhysDimUOMJoin
                where whsPhysDimUOMJoin.ItemId == salesLine.ItemId
                && whsPhysDimUOMJoin.UOM == salesLine.SalesUnit;
            if (whsPhysDimUOMJoin.RecId)
            {
                continue;
            }

            ttsbegin;

            factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        whsPhysDimUOM.ItemId,
                        salesLine.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(whsPhysDimUOM.UOM),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(salesLine.SalesUnit),
                        NoYes::No,
                        NoYes::No);
            if (factor)
            {
                metOrderExtractScreenTmp.Weight += salesLine.SalesQty * (whsPhysDimUOM.Weight/factor);
                metOrderExtractScreenTmp.Volume += salesLine.SalesQty * (whsPhysDimUOM.displayVolume()/factor);
            }
            metOrderExtractScreenTmp.update();
            ttscommit;
        }

        METItemTypes        itemTypes;
        volumeMap           = new Map (Types::String, Types::Real);
       
        //Case5: Update ItemType, Case, Broken case
        while select forupdate metOrderExtractScreenTmp
            join  ItemId, SalesQty, SalesUnit, InventDimId from salesLine
                where  salesLine.SalesStatus == SalesStatus::Backorder
                && salesLine.SalesQty > 0
                && salesLine.SalesId == metOrderExtractScreenTmp.SalesId
            join InventSiteId, InventLocationId from inventDim
                where inventDim.inventDimId == salesLine.InventDimId
                && (!site || inventDim.InventSiteId == site)
                && (!warehouse || inventDim.InventLocationId == warehouse)
            join ItemType from itemSiteSettings
                where itemSiteSettings.ItemId == salesLine.ItemId
                &&  itemSiteSettings.InventSiteId == inventDim.InventSiteId
                &&  itemSiteSettings.FilterCode1 == metOrderExtractScreenTmp.FilterCodeOne
        {
            //Calculate volume by warehouse. This will be required to calculate total pallets.
            if (volumeMap.exists(inventDim.InventLocationId))
            {
                volumeMap.insert(inventDim.InventLocationId, metOrderExtractScreenTmp.Volume +  volumeMap.lookup(inventDim.InventLocationId));
            }
            else
            {
                volumeMap.insert(inventDim.InventLocationId, metOrderExtractScreenTmp.Volume);
            }

            //If there are multiple items in the order with different item type then show Multiple*
            if (!itemTypes)
            {
                itemTypes = itemSiteSettings.ItemType;
            }
            else if(itemTypes != itemSiteSettings.ItemType)
            {
                itemTypes = METConstants::ItemTypeMultiple;
            }
            ttsbegin;
            metOrderExtractScreenTmp.reread();
            metOrderExtractScreenTmp.ItemType   =   itemTypes;
            metOrderExtractScreenTmp.Cases      +=  salesLine.displayMETcases();
            metOrderExtractScreenTmp.BrokenCase +=  salesLine.displayMETBrokenCase();
            metOrderExtractScreenTmp.update();
            ttscommit;
        }

        //Calculate total pallets
        if (volumeMap && volumeMap.elements())
        {
            mapEnum = volumeMap.getEnumerator();

            while (mapEnum.moveNext())
            {
                //Calculate pallets
                metInventLocation = METInventLocation::findByInventLocationId(mapEnum.currentKey());
                if (metInventLocation.WHSPalletVolume)
                {
                    totalPallets += any2Int((mapEnum.currentValue()/metInventLocation.WHSPalletVolume));
                }
            }
        }
        this.parmTotalpallets(totalPallets);

    }

    /// <summary>
    /// Constructs the order extract screen.
    /// </summary>
    /// <param name="_metOrderExtractScreenTmp">
    /// The <c>METOrderExtractScreenTmp</c> instance.
    /// </param>
    /// <param name="_metOrderExtractScreenParameters">
    /// An instance of <c>METOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    /// <returns>METOrderExtractScreenProcessor class instance.</returns>
    public static METOrderExtractScreenProcessor construct(
        METOrderExtractScreenTmp                _metOrderExtractScreenTmp,
        METOrderExtractScreenParameters         _metOrderExtractScreenParameters)
    {
        METOrderExtractScreenProcessor   metOrderExtractScreenProcessor;

        metOrderExtractScreenProcessor = new METOrderExtractScreenProcessor();

        metOrderExtractScreenProcessor.populateOrderExtractScreen(_metOrderExtractScreenTmp, _metOrderExtractScreenParameters);

        return metOrderExtractScreenProcessor;
    }

/// <summary>
/// Initialise parameters.
/// </summary>
protected void initParams()
{
    site                = metOrderExtractScreenParameters.parmSite();
    warehouse           = metOrderExtractScreenParameters.parmWarehouse();
    route               = metOrderExtractScreenParameters.parmRoute();
    shippingDatefrom    = metOrderExtractScreenParameters.parmShippingDateConfirmFrom();
    shippingDateTo      = metOrderExtractScreenParameters.parmShippingDateConfirmTo();
    category            = metOrderExtractScreenParameters.parmCategory();
    extracted           = metOrderExtractScreenParameters.parmExtracted();
}

    /// <summary>
    /// Populates <c>METOrderExtractScreenTmp</c> table for the grid on the order extract screen form.
    /// </summary>
    /// <param name="_metOrderExtractScreenTmp">
    /// The <c>METOrderExtractScreenTmp</c> instance.
    /// </param>
    /// <param name="_metOrderExtractScreenParameters">
    /// An instance of <c>METOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    public void populateOrderExtractScreen(METOrderExtractScreenTmp                _metOrderExtractScreenTmp,
                                            METOrderExtractScreenParameters         _metOrderExtractScreenParameters)
    {
        METOrderExtractScreenProcessor           metOrderExtractScreenProcessor;

        metOrderExtractScreenProcessor = new METOrderExtractScreenProcessor();

        metOrderExtractScreenProcessor.parmMETOrderExtractScreenParams(_metOrderExtractScreenParameters);
        metOrderExtractScreenProcessor.parmMETOrderExtractScreenTmp(_metOrderExtractScreenTmp);
        metOrderExtractScreenProcessor.initParams();
        metOrderExtractScreenProcessor.insertOrders();
        this.parmTotalpallets(metOrderExtractScreenProcessor.parmTotalpallets());
    }
